 const stick=document.querySelector('#stick'),nub=document.querySelector('#nub');let joy={x:0,y:0},joyId=null;stick.addEventListener('pointerdown',e=>{joyId=e.pointerId;stick.setPointerCapture(joyId);moveJoy(e)});stick.addEventListener('pointermove',e=>{if(e.pointerId===joyId)moveJoy(e)});function moveJoy(e){let r=stick.getBoundingClientRect(),dx=e.clientX-(r.left+r.width/2),dy=e.clientY-(r.top+r.height/2),m=Math.min(38,Math.hypot(dx,dy)),a=Math.atan2(dy,dx);joy.x=Math.cos(a)*m/38;joy.y=Math.sin(a)*m/38;nub.style.transform=`translate(${joy.x*38}px,${joy.y*38}px)`}function endJoy(){joy={x:0,y:0};joyId=null;nub.style.transform=''}stick.addEventListener('pointerup',endJoy);stick.addEventListener('pointercancel',endJoy);
